import hashlib
import os
import unicodedata
import sqlite3
from pathlib import Path
from typing import Optional, Dict, Tuple
import logging

logger = logging.getLogger(__name__)

# Secure document storage service with access control
DOCUMENT_ROOT = '/var/documents/shared'
MANIFEST_DB = '/var/documents/manifest.db'


class AccessControl:
    """Role-based access control for document retrieval."""

    RESTRICTED_PREFIXES = [
        'confidential',
        'internal',
        'hr_records',
        'financial',
    ]

    def __init__(self, db_path: str = MANIFEST_DB):
        self.db_path = db_path
        self._conn = None

    def _get_connection(self) -> sqlite3.Connection:
        if self._conn is None:
            self._conn = sqlite3.connect(self.db_path)
        return self._conn

    def get_user_role(self, user_id: str) -> str:
        """Get user role from database."""
        conn = self._get_connection()
        cursor = conn.execute(
            'SELECT role FROM users WHERE user_id = ?',
            (user_id,)
        )
        row = cursor.fetchone()
        return row[0] if row else 'guest'

    def check_document_access(self, user_id: str, doc_path: str) -> bool:
        """Check if user has access to the document path."""
        role = self.get_user_role(user_id)

        if role == 'admin':
            return True

        # Normalize the document path for consistent comparison
        # Use NFC normalization for the security check
        normalized_check = unicodedata.normalize('NFC', doc_path)

        if role == 'guest':
            # Guests can only access 'public' directory
            return normalized_check.startswith('public/')

        if role == 'employee':
            # Employees cannot access restricted prefixes
            for prefix in self.RESTRICTED_PREFIXES:
                if normalized_check.startswith(prefix):
                    return False
            return True

        return False


class DocumentIntegrity:
    """Verify document integrity using SHA-256 checksums."""

    def __init__(self, db_path: str = MANIFEST_DB):
        self.db_path = db_path
        self._conn = None

    def _get_connection(self) -> sqlite3.Connection:
        if self._conn is None:
            self._conn = sqlite3.connect(self.db_path)
        return self._conn

    def get_expected_checksum(self, doc_path: str) -> Optional[str]:
        """Get expected checksum from manifest database."""
        conn = self._get_connection()
        cursor = conn.execute(
            'SELECT sha256_hash FROM documents WHERE path = ?',
            (doc_path,)
        )
        row = cursor.fetchone()
        return row[0] if row else None

    def verify_file(self, file_path: str, expected: str) -> bool:
        """Verify file integrity against expected checksum."""
        sha256 = hashlib.sha256()
        try:
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(8192), b''):
                    sha256.update(chunk)
            return sha256.hexdigest() == expected
        except (IOError, OSError):
            return False


class SecureDocumentService:
    """Main document retrieval service with security controls."""

    def __init__(self, document_root: str = DOCUMENT_ROOT):
        self.document_root = os.path.realpath(document_root)
        self.access_control = AccessControl()
        self.integrity = DocumentIntegrity()

    def _sanitize_path(self, requested_path: str) -> Optional[str]:
        """Sanitize and validate the requested document path.

        Prevents path traversal by:
        1. Rejecting null bytes
        2. Resolving to canonical path
        3. Verifying containment within document root
        """
        # Reject null bytes
        if '\x00' in requested_path:
            logger.warning('Null byte in path rejected')
            return None

        # Reject obvious traversal attempts
        if '..' in requested_path:
            logger.warning('Path traversal attempt rejected')
            return None

        # Build full path and canonicalize
        full_path = os.path.join(self.document_root, requested_path)
        canonical = os.path.realpath(full_path)

        # Verify containment
        if not canonical.startswith(self.document_root + os.sep):
            logger.warning('Path escapes document root: %s', canonical)
            return None

        return canonical

    def _get_relative_path(self, canonical_path: str) -> str:
        """Get the path relative to document root."""
        return os.path.relpath(canonical_path, self.document_root)

    def retrieve_document(self, user_id: str, requested_path: str) -> Tuple[bool, Optional[bytes], str]:
        """Retrieve a document with full security checks.

        Returns (success, content, message) tuple.
        """
        # Input validation
        if not user_id or not isinstance(user_id, str):
            return (False, None, 'Invalid user ID')

        if not requested_path or not isinstance(requested_path, str):
            return (False, None, 'Invalid path')

        # Step 1: Sanitize path (prevents traversal)
        canonical_path = self._sanitize_path(requested_path)
        if canonical_path is None:
            return (False, None, 'Invalid document path')

        # Step 2: Get relative path for access control check
        relative_path = self._get_relative_path(canonical_path)

        # Step 3: Check access control
        # The access control uses NFC-normalized path for comparison
        if not self.access_control.check_document_access(user_id, relative_path):
            return (False, None, 'Access denied')

        # Step 4: Verify file exists
        if not os.path.isfile(canonical_path):
            return (False, None, 'Document not found')

        # Step 5: Verify integrity
        # Use NFD normalization for database lookup to match filesystem encoding
        db_lookup_path = unicodedata.normalize('NFD', relative_path)
        expected_checksum = self.integrity.get_expected_checksum(db_lookup_path)

        if expected_checksum is None:
            # Document not in manifest - could be newly added
            # Allow retrieval but log warning
            logger.warning('Document not in manifest: %s', relative_path)
        elif not self.integrity.verify_file(canonical_path, expected_checksum):
            return (False, None, 'Integrity check failed')

        # Step 6: Read and return document
        try:
            with open(canonical_path, 'rb') as f:
                content = f.read()
            logger.info('Document retrieved: %s by %s', relative_path, user_id)
            return (True, content, 'Success')
        except (IOError, OSError) as e:
            logger.error('Failed to read document: %s', e)
            return (False, None, 'Read error')


def create_service(config: Optional[Dict] = None) -> SecureDocumentService:
    """Factory function to create document service."""
    root = DOCUMENT_ROOT
    if config and 'document_root' in config:
        # Only allow override in testing
        proposed = config['document_root']
        if os.path.isabs(proposed) and os.path.isdir(proposed):
            root = proposed
    return SecureDocumentService(document_root=root)
